'use client'

/**
 * useFocusOnRouteChange
 *
 * Moves focus to the <main id="main-content"> element after every client-side
 * navigation. This satisfies WCAG 2.4.3 and allows screen readers to announce
 * the new page without requiring a manual tab stop.
 *
 * Usage: call once in a layout-level Client Component (e.g. inside AppHeader).
 * The hook is a no-op when main#main-content is absent.
 */
import { useEffect, useRef } from 'react'
import { usePathname } from 'next/navigation'

export function useFocusOnRouteChange() {
  const pathname = usePathname()
  const prevPathname = useRef<string>(pathname)

  useEffect(() => {
    if (pathname === prevPathname.current) return
    prevPathname.current = pathname

    // Defer one tick so RSC streaming has painted the new content
    const id = setTimeout(() => {
      const main = document.getElementById('main-content')
      if (main) {
        main.focus({ preventScroll: false })
      }
    }, 50)

    return () => clearTimeout(id)
  }, [pathname])
}

